        Evidence.OwSet(owords, 1, Evidence.HdTstart(), 5);
        Evidence.OwSet(owords, 1, Evidence.HdConf(), 500);
        emon.Testport.AssertEq(Scan.ScXtraOk(owords, etext, 0, 1, 1), 1, "a numeric column retains its lower rescue bound");
    }
    [Xunit.Fact]
    public static void TestLaterPassRescueExtendsTheFirstPassLineRatherThanFillingHolesOrPrefixingProse() {
        emon.Port.Cells owords = emon.Port.NewCells();
        emon.Port.Cells etext = emon.Port.NewCells();
        emon.Port.CellsPush(etext, 49);
        Evidence.OwNew(owords, 1, 200, 0, 300, 100, 200, 100, 300, 100, 0, 0, 0, 1, 0, 900, -1);
        Evidence.OwNew(owords, 1, 600, 0, 700, 100, 600, 100, 700, 100, 0, 0, 0, 1, 0, 900, -1);
        Evidence.OwNew(owords, 1, 400, 0, 500, 100, 400, 100, 500, 100, 0, 0, 0, 1, 1, 900, -1);
        Evidence.OwSet(owords, 2, Evidence.OwfRun(), 1);
        emon.Testport.AssertEq(Scan.ScXtraOk(owords, etext, 0, 2, 2), 0, "an interior gap can be overlay ink, rather than a lost column");
        Evidence.OwSet(owords, 2, Evidence.HdX0(), 800);
        Evidence.OwSet(owords, 2, Evidence.HdX1(), 900);
        emon.Testport.AssertEq(Scan.ScXtraOk(owords, etext, 0, 2, 2), 1, "the amount beyond the first pass's end is recovered");
        Evidence.OwSet(owords, 2, Evidence.HdX0(), 0);
        Evidence.OwSet(owords, 2, Evidence.HdX1(), 100);
        emon.Testport.AssertEq(Scan.ScXtraOk(owords, etext, 0, 2, 2), 0, "a new prefix is not the missing trailing column");
    }
    internal static int SctDirectDct(string file) {
        emon.Port.Src src = emon.Port.SrcOfBlob(emon.Testport.TestFile(file));
        emon.Port.Cells ar = emon.Port.NewCells();
        emon.Port.Cells dc = emon.Port.NewCells();
        emon.Port.Cells a = emon.Port.NewCells();
        emon.Port.Cells b = emon.Port.NewCells();
        emon.Port.Cells st = emon.Port.NewCells();
        emon.Port.Cells sp = emon.Port.NewCells();
        if (Pdfdoc.PdOpen(src, ar, dc, a, b, st) != 0) {
            return -1;
        }
        return Scan.ScDctSpan(src, ar, dc, a, b, st, 5, sp);
    }
    [Xunit.Fact]
    public static void TestAScanJpegOutsideTheSharedNativeSubsetIsRenderedRatherThanDecodedDirectly() {
        emon.Testport.AssertEq(SctDirectDct("assets/dct-arith.pdf"), 0, "arithmetic JPEG needs page rendering, not a host-dependent native decode");
        emon.Testport.AssertEq(SctDirectDct("assets/dct-cmyk.pdf"), 0, "CMYK also needs rendering for scan OCR");
        emon.Testport.AssertEq(SctDirectDct("assets/dct-decode.pdf"), 1, "ordinary 8-bit three-component JPEG stays on the direct path");
        emon.Testport.AssertEq(SctDirectDct("assets/dct-a85-decode.pdf"), 0, "a filter chain still needs rendering");
    }
    [Xunit.Fact]
    public static void TestAConfidentIsolatedDotSpeckIsKeptOutOfTheBody() {
        emon.Port.Cells olines = emon.Port.NewCells();
        emon.Port.Cells owords = emon.Port.NewCells();
        emon.Port.Cells words = emon.Port.NewCells();
        emon.Port.Cells lines = emon.Port.NewCells();
        emon.Port.Cells et = emon.Port.NewCells();
        StWord(owords, et, 100, 200, 950, 0, 46, 0, 0, 0, 0, 0, 0, 0);
        StLine(olines, 100, 200, 0, 1);
        emon.Testport.AssertEq(StEmit(olines, owords, words, lines, et, emon.Port.NewCells(), 1), 0, "a one-point dot alone is no paragraph even at high engine confidence");
        emon.Testport.AssertEq(Evidence.OwGet(owords, 0, Evidence.OwfFlags()) & Evidence.OeGarbage(), Evidence.OeGarbage(), "the evidence retains it for the garbage ledger");
    }
    [Xunit.Fact]
    public static void TestOcrTrustSeparatesCleanWordsFromJunk() {
        emon.Port.Cells ow = emon.Port.NewCells();
        emon.Port.Cells et = emon.Port.NewCells();
        emon.Port.CellsPush(et, 84);
        emon.Port.CellsPush(et, 111);
        emon.Port.CellsPush(et, 116);
        emon.Port.CellsPush(et, 97);
        emon.Port.CellsPush(et, 108);
        emon.Port.CellsPush(et, 65533);
        emon.Port.CellsPush(et, 124);
        emon.Port.CellsPush(et, 65533);
        Evidence.OwNew(ow, 1, 0, 0, 500, 100, 0, 100, 500, 100, 0, 0, 0, 5, 0, 960, -1);
        Evidence.OwNew(ow, 1, 0, 200, 500, 300, 0, 300, 500, 300, 0, 0, 5, 3, 1, 120, -1);
        Evidence.OwSet(ow, 0, Evidence.OwfFlags(), 1);
        emon.Testport.AssertThat(Scan.ScWordTrust(ow, et, 0) >= 850, "clean dictionary OCR stays high");
        emon.Testport.AssertThat(Scan.ScWordTrust(ow, et, 1) <= 200, "rejected characters at low engine confidence stay low");
        emon.Testport.AssertThat((Scan.ScWordTrust(ow, et, 0) - Scan.ScWordTrust(ow, et, 1)) >= 600, "scrapers can separate clean text and junk");
    }
    [Xunit.Fact]
    public static void TestOcrFormatControlsAndUnspacedScripts() {
        emon.Testport.AssertEq(Scan.ScFormatControl(8206), 1, "OCR LRM is stripped");
        emon.Testport.AssertEq(Scan.ScFormatControl(8207), 1, "OCR RLM is stripped");
        emon.Testport.AssertEq(Scan.ScFormatControl(8295), 1, "OCR direction isolates are stripped");
        emon.Testport.AssertEq(Scan.ScFormatControl(1575), 0, "Arabic letters are kept");
        emon.Testport.AssertEq(Scan.ScUnspaced(21407), 1, "Han words have no separator");
        emon.Testport.AssertEq(Scan.ScUnspaced(12363), 1, "Kana words have no separator");
        emon.Testport.AssertEq(Scan.ScUnspaced(44032), 0, "Hangul word spaces are kept");
        emon.Testport.AssertEq(Scan.ScUnspaced(65), 0, "Latin word spaces are kept");
    }
    [Xunit.Fact]
    public static void TestOcrPassDisagreementReducesTrust() {
        emon.Port.Cells ow = emon.Port.NewCells();
        emon.Port.Cells et = emon.Port.NewCells();
        emon.Port.CellsPush(et, 65);
        emon.Port.CellsPush(et, 66);
        Evidence.OwNew(ow, 1, 0, 0, 500, 100, 0, 100, 500, 100, 0, 0, 0, 1, 0, 900, -1);
        Evidence.OwNew(ow, 1, 0, 0, 500, 100, 0, 100, 500, 100, 0, 0, 1, 1, 1, 900, -1);
        Evidence.OwSet(ow, 0, Evidence.OwfRun(), 0);
        Evidence.OwSet(ow, 1, Evidence.OwfRun(), 1);
        emon.Testport.AssertThat(Scan.ScWordAgreement(ow, et, 0) < 1000, "two readings of the same ink disagree");
        Evidence.OwSet(ow, 1, Evidence.HdTstart(), 0);
        emon.Testport.AssertEq(Scan.ScWordAgreement(ow, et, 0), 1000, "the same reading agrees");
    }
